import{_ as l,o as t,c as i,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"Ceph Performance Meeting 2022-06-23","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-06-23","date":"2022-06-23T00:00:00.000Z","updated":"2022-06-28T00:00:00.000Z","tags":["Ceph","性能优化","RocksDB","Snapmapper","代码重构"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-06-23.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-06-23.md","lastUpdated":1780460162000}'),p={name:"posts/2022/Ceph_Performance_Meeting_2022-06-23.md"};function o(r,e,n,s,_,c){return t(),i("div",null,[...e[0]||(e[0]=[a("<p>会议纪要：</p><ol><li><p><strong>更新情况</strong>：</p><ul><li>移除<code>statifus</code>的更新已通过Adam审查并被批准，Igor进行了修改，但仍需核心团队再次审查。</li><li>将<code>kodell</code>添加到Blue Store以缓解缓冲区膨胀问题的更新正在积极审查中，Sam提出了多项更改请求。</li></ul></li><li><p><strong>讨论主题</strong>：</p><ul><li>关于RocksDB调优，测试显示调整内存缓冲区数量和大小，并允许累积两次写入，并未产生预期中的放大增加。通过调整Level 0和Level 1，并使用更多较小的缓冲区累积成较大的刷新，可以在不显著增加写放大的情况下提高RBD性能。</li><li>正在研究经典OSD中的分片和线程行为，发现空分片时效率会显著下降。</li></ul></li><li><p><strong>Gabby报告</strong>：</p><ul><li>Gabby正在重写Snapmapper的全部代码，优化内存使用。新的版本将尝试将所有内容存储在内存中，并使用Snap ID和PG确定存储库的使用，优化数据结构从Red-Black树变为哈希表。</li></ul></li><li><p><strong>行动计划</strong>：</p><ul><li>Gabby将继续Snapmapper项目，并在下次会议前提供更新。</li><li>其他成员将继续审查和测试现有更新，并在必要时提供反馈。</li><li>下次会议将在一周后召开，进一步讨论这些主题和任何新的进展。</li></ul></li></ol><p>改进点：</p><ul><li>确保包含所有关键更新和讨论主题。</li><li>添加了关于Snapmapper项目的更多细节。</li><li>简化了行动计划的部分，使其更加清晰。</li></ul>",4)])])}const u=l(p,[["render",o]]);export{m as __pageData,u as default};
